/* ============================================================================
 * builtin-bg.js — 内置背景图（随应用一起分发）
 * ----------------------------------------------------------------------------
 * 为什么把图**内嵌成 base64**，而不是放成 assets/img/xxx.jpg：
 *   内置图需要在首次启动时导入进背景库（要重新压缩 + 生成缩略图），
 *   而这一步要把它画到 canvas 上。**file:// 页面里加载 file:// 图片会把
 *   canvas 污染（tainted）**，随后 toDataURL() 直接抛 SecurityError ——
 *   APK 的第 2/3 步兜底正好跑在 file:// 下，那样内置图就导不进来。
 *   dataURL 是同源的，画进 canvas 不会被污染，任何环境都能用。
 * 代价就是体积：这张图 base64 之后约 317 KB，直接进 HTML。
 *
 * 这张图是 1920×1080 的 JPEG（q0.78）。导入时仍会按设备分辨率再压一次，
 * 存进 IndexedDB，和用户自己导入的图**完全同等待遇，可以随时删除**。
 * 删掉之后不会再自动回来（dash.bg.seeded 里记了已种过的 id）。
 * ==========================================================================*/
(function (global) {
  'use strict';
  global.DASH_BUILTIN_BG = [
    {
      id: 'summer-light',
      name: '光斑回眸夏日温柔',
      w: 1920, h: 1080,
      data: 'data:image/jpeg;base64,'
    }
  ];
})(window);
